let checks=0;const check=(name,fn)=>{fn();checks++;console.log('PASS',name);};
const setup=()=>{const s=SIM.initial();s.master.scenic??={...buildingAccess(s,s.buildings.find(b=>b.type==='hall')),path:[],steps:0,facing:1,back:false};E.initEconomy(s);P.initPersons(s);W.initWeather(s);O.initOrganization(s);return s;};
const transportTotal=(s,k)=>Object.values(s.stockpilesById).reduce((n,st)=>n+st.resources[k],0)+Object.values(s.workOrdersById).filter(w=>w.kind==='transport'&&!['delivered','cancelled'].includes(w.phase)).reduce((n,w)=>n+(w.cargo[k]||0),0);
check('SR-XF-007 AC01/02 stable recipe and shared identity persist JSON',()=>{const s=setup(),before=P.viewPersons(s);assert.ok(Object.keys(s.personsById).length>=3);const re=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.deepEqual(P.viewPersons(re),before);assert.notDeepEqual(s.personsById['person:lu-zhiwei'].appearance.recipe,s.personsById['person:lin-changfeng'].appearance.recipe);});
check('SR-XF-007 AC03 truthful painted action/fallback',()=>{const s=setup();s.master.action='study';const v=P.appearanceView(s,'person:master');assert.equal(v.action,'study');assert.equal(v.tool,'book');assert.equal(v.fullAnimationAvailable,false);assert.equal(v.asset,'yunxiu-courtyard:characters:v1');assert.match(v.fallback,/专用连续身体动作尚未绘制/);s.master.action='unknown';assert.equal(P.appearanceView(s,'person:master').fullAnimationAvailable,false);assert.ok(P.appearanceView(s,'person:master').fallback);s.master.scenic.path=[{x:s.master.scenic.x+1,y:s.master.scenic.y}];assert.equal(P.appearanceView(s,'person:master').action,'walk');});
check('SR-XF-008 AC01 repeated invitation stable and no hidden motives',()=>{const s=setup(),p=s.personsById['person:lu-zhiwei'];s.homeMemberIds.push(p.personId);const b=s.buildings.find(b=>b.type==='farm')||s.buildings[0];const a=P.inviteWork(s,p.personId,b.id),again=P.inviteWork(s,p.personId,b.id);assert.deepEqual(a,again);const before=JSON.stringify(s);P.viewPersons(s);assert.equal(JSON.stringify(s),before);p.schedule.privateMotives=['secret'];assert.ok(!JSON.stringify(P.viewPersons(s)).includes('secret'));});
check('SR-XF-008 AC02 five people two real stations only two execute, others outside',()=>{const s=setup();initSpatial(s);const id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'lumber',x:3,y:3,level:1,condition:100,enabled:true,progress:0,transform:{x:36,y:16,orientation:'south'}};s.buildings.push(b);s.buildings.push({id:s.nextId++,type:'house',x:5,y:5,level:1,condition:100,enabled:true,progress:0,transform:{x:36,y:28,orientation:'south'}});E.initEconomy(s);const slots=facilitySlots(s,b,'work');assert.equal(slots.length,2);const people=[];for(let i=0;i<5;i++){const p=SIM.addDisciple(s,{name:`工位验收${i}`,talent:1,traits:[80,40,80,80,40]});p.wound=0;p.energy=100;p.job=b.id;p.mind.activity='work';p.mind.satiety=100;p.mind.scenic={...p.mind.scenic,...buildingAccess(s,b),path:[],goal:null};people.push(p);}for(let tick=0;tick<80;tick++){s.worldTick++;for(const p of people)prepareFacilityActivity(s,p,b,'work',46);}const activities=people.map(p=>s.activitiesById[p.activityId]);assert.equal(activities.filter(a=>a.phase==='executing').length,2);assert.equal(activities.filter(a=>a.phase==='waiting').length,3);assert.equal(new Set(activities.filter(a=>a.slotId).map(a=>a.slotId)).size,2);const waiting=activities.filter(a=>a.phase==='waiting');assert.ok(waiting.every(a=>a.waitingPosition));assert.equal(new Set(waiting.map(a=>JSON.stringify(a.waitingPosition))).size,3);validateFacilityActivities(s);const worker=people.find(p=>s.activitiesById[p.activityId].phase==='executing'),activity=s.activitiesById[worker.activityId];worker.mind.away={kind:'test'};const before=Object.keys(s.reservationsById).length;reconcileActivities(s);assert.equal(worker.activityId,null);assert.equal(Object.keys(s.reservationsById).length,before-1);assert.equal(contributeProduction(s,worker,b,()=>true),false); // Body release prevents an absent worker from producing.
});
check('SR-XF-009 AC01 finite source cannot produce when depleted',()=>{const s=setup();s.srEconomy.patches.herb.remaining=0;assert.equal(E.productionAvailability(s,{type:'farm',instanceId:'building:yunxiu:999'}).available,false);assert.equal(E.consumeHarvest(s,'herb',1),false);assert.equal(E.consumeHarvest(s,'wood',10),true);assert.equal(s.srEconomy.patches.wood.remaining,710);});
check('SR-XF-009 AC02 full output preflight, no silent clipping or double settlement',()=>{const s=setup(),b=s.buildings.find(b=>b.type==='farm')||{type:'farm',instanceId:'building:yunxiu:999',level:1};if(!s.buildingsById[b.instanceId])s.buildings.push({...b,id:999,x:3,y:3,condition:100,enabled:true,progress:0});E.initEconomy(s);const st=s.stockpilesById[`stockpile:${b.instanceId}`],id=`work:production:${b.instanceId}`;s.workOrdersById[id]={batch:1};const participants=[{person:s.master,share:1}],settle=(ps,target)=>{target.resources.herb+=20;target.stats.crafted++;return true;};st.capacity=15;const before=JSON.stringify(s);assert.equal(E.settleFiniteProduction(s,b,settle,participants),false);assert.equal(JSON.stringify(s),before);st.capacity=320;const herbs=s.resources.herb;assert.equal(E.settleFiniteProduction(s,b,settle,participants),true);assert.equal(st.resources.herb,20);assert.equal(s.resources.herb,herbs);assert.equal(s.srEconomy.patches.herb.remaining,140);assert.ok(s.factsById[`fact:production:${b.instanceId}:1`]);});
check('SR-XF-009/010 actual public command harvest→carry→transport→save',()=>{let s=SIM.initial({sr:true});s.master.wound=0;s.master.energy=100;s.master.activityId=null;const before=s.resources.wood,patch=s.srEconomy.patches.wood.remaining;s=SIM.dispatchCommand(s,{name:'startMasterHarvest',args:['wood']}).state;for(let n=0;n<260;n++)SIM.tick(s,.1);assert.equal(s.resources.wood,before);assert.equal(s.srEconomy.patches.wood.remaining,patch-12);assert.equal(s.stockpilesById['stockpile:carried:master'].resources.wood,12);s=SIM.dispatchCommand(s,{name:'startTransport',args:['stockpile:carried:master','stockpile:yunxiu','person:master',{wood:12}]}).state;for(let n=0;n<150;n++)SIM.tick(s,.1);assert.equal(s.resources.wood,before+12);assert.equal(s.stockpilesById['stockpile:carried:master'].resources.wood,0);const re=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.equal(re.resources.wood,s.resources.wood);assert.equal(re.srEconomy.patches.wood.remaining,s.srEconomy.patches.wood.remaining);});
check('SR-XF-010 AC01 source/reserved/carried/delivered conservation',()=>{const s=setup(),home=s.stockpilesById['stockpile:yunxiu'];const targetId='stockpile:test-site';s.stockpilesById[targetId]={id:targetId,ownerId:'person:master',custodianId:'person:master',access:'public',capacity:100,position:{...home.position},resources:Object.fromEntries(Object.keys(home.resources).map(k=>[k,0]))};s.master.scenic={...s.master.scenic,...home.position,path:[]};s.master.wound=0;s.master.energy=100;const t=transportTotal(s,'wood'),r=E.startTransport(s,home.id,targetId,'person:master',{wood:10});s.master.action='walk';assert.equal(transportTotal(s,'wood'),t);assert.equal(s.stockpilesById[targetId].resources.wood,0);s.worldTick++;E.tickEconomy(s);assert.equal(s.workOrdersById[r.id].phase,'carrying');s.worldTick++;E.tickEconomy(s);assert.equal(s.workOrdersById[r.id].phase,'delivered');assert.equal(transportTotal(s,'wood'),t);assert.equal(s.stockpilesById[targetId].resources.wood,10);assert.equal(s.master.action,'rest','completed transport clears the stale walking action before the next command');SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.throws(()=>E.cancelTransport(s,r.id));});
check('SR-XF-010 AC02 carried injury/cancel/reload leaves one cargo location',()=>{const s=setup(),home=s.stockpilesById['stockpile:yunxiu'],targetId='stockpile:test-away';s.stockpilesById[targetId]={...structuredClone(home),id:targetId,position:{...home.position,x:home.position.x+12},resources:Object.fromEntries(Object.keys(home.resources).map(k=>[k,0]))};s.master.scenic={...s.master.scenic,...home.position,path:[]};s.master.wound=0;s.master.energy=100;const t=transportTotal(s,'wood'),r=E.startTransport(s,home.id,targetId,'person:master',{wood:10});s.worldTick++;E.tickEconomy(s);s.master.wound=50;s.worldTick++;E.tickEconomy(s);assert.equal(s.workOrdersById[r.id].phase,'carrying');const cancelled=E.cancelTransport(s,r.id);assert.ok(cancelled.returnedTo.startsWith('stockpile:dropped:'));assert.equal(transportTotal(s,'wood'),t);assert.throws(()=>E.cancelTransport(s,r.id));const restored=JSON.parse(JSON.stringify(s));E.validateEconomy(restored);assert.equal(transportTotal(restored,'wood'),t);});
check('SR-XF-010 AC03 private/merchant goods blocked and cross-scene transport blocked',()=>{const s=setup();assert.throws(()=>E.startTransport(s,'stockpile:qingxi','stockpile:yunxiu','person:master',{wood:10}),/跨地点/);const privateId='stockpile:lu-zhiwei',p=s.stockpilesById[privateId];p.resources.herb=10;assert.throws(()=>E.startTransport(s,privateId,'stockpile:yunxiu','person:master',{herb:1}),/无权/);});
check('SR-XF-011 AC01 order settles once and survives reload',()=>{const s=setup();s.resources.herb=60;const a=E.marketOrder(s,'gu_medicine','accept'),before=s.resources.herb;assert.equal(before,40);assert.deepEqual(E.marketOrder(s,'gu_medicine','accept'),a);s.worldTick=300;E.tickEconomy(s);const jade=s.resources.jade;E.marketOrder(s,'gu_medicine','deliver');assert.equal(s.resources.jade,jade+24);assert.throws(()=>E.marketOrder(s,'gu_medicine','deliver'));const re=JSON.parse(JSON.stringify(s));E.validateEconomy(re);assert.equal(re.srEconomy.orders.gu_medicine.phase,'completed');});
check('SR-XF-011 AC02 closed route blocks restock and direct merchant access',()=>{const s=setup();s.srWorld={routes:{'route:bridge':{id:'route:bridge',condition:'blocked'}}};s.worldTick=2400;const before=s.stockpilesById['stockpile:qingxi'].resources.herb;E.tickEconomy(s);assert.equal(s.stockpilesById['stockpile:qingxi'].resources.herb,before);assert.throws(()=>E.marketTrade(s,'herb','buy'));});
check('SR-XF-011 AC03 finite merchant capital and no buy/sell profit loop',()=>{const s=setup();s.worldTick=300;const jade=s.resources.jade;E.marketTrade(s,'herb','buy');E.marketTrade(s,'herb','sell');assert.ok(s.resources.jade<jade);s.stockpilesById['stockpile:qingxi'].resources.jade=0;assert.throws(()=>E.marketTrade(s,'herb','sell'),/本金/);});
check('SR-XF-019 AC01 bulk world tick replay equals individual boundaries',()=>{const a=setup(),b=cloneState(a);a.worldTick=1800;W.tickWeather(a);for(let i=1;i<=1800;i++){b.worldTick=i;W.tickWeather(b);}assert.deepEqual(a.weatherByRegionId,b.weatherByRegionId);assert.deepEqual(a.ecologiesBySceneId,b.ecologiesBySceneId);assert.deepEqual(a.srEconomy.patches,b.srEconomy.patches);const before=JSON.stringify(a);W.viewWeather(a);assert.equal(JSON.stringify(a),before);});
check('SR-XF-019 AC02 drainage gives actual crop/wetness difference',()=>{const a=setup(),b=cloneState(a);for(const s of [a,b]){s.weatherByRegionId['region:yunxiu'].phase='rain';s.weatherByRegionId['region:yunxiu'].nextPhaseAtTick=99999;}b.ecologiesBySceneId['scene:yunxiu-courtyard'].surfaceZones['zone:yard-path'].drainage=1;for(let i=1;i<=1000;i++){a.worldTick=i;b.worldTick=i;W.tickWeather(a);W.tickWeather(b);}assert.ok(a.ecologiesBySceneId['scene:yunxiu-courtyard'].surfaceZones['zone:yard-path'].wetness>b.ecologiesBySceneId['scene:yunxiu-courtyard'].surfaceZones['zone:yard-path'].wetness);assert.ok(a.srEconomy.patches.herb.remaining<b.srEconomy.patches.herb.remaining);});
check('SR-XF-026 AC01 specialist founding does not require 12-person lock',()=>{const s=setup();s.master.realm=10;s.master.knowledge.qingyuan=70;s.homeMemberIds=['person:lu-zhiwei','person:lin-changfeng'];if(!s.buildings.some(b=>b.type==='library'))s.buildings.push({id:s.nextId++,type:'library',x:2,y:2,level:1,condition:100,enabled:true,progress:0});Object.assign(s.resources,{jade:400,wood:150,stone:150,insight:50,food:100});assert.equal(O.foundingStatusSR(s).ready,false);s.society.stats.workCycles=1;assert.equal(O.foundingStatusSR(s).ready,true);O.foundSectSR(s,'三人云岫');assert.equal(s.society.formal,true);assert.equal(s.sect.founded,true);});
check('SR-XF-026 AC03 policy is versioned, non-retroactive, notice delayed',()=>{const s=setup();s.homeMemberIds=['person:lu-zhiwei'];const value=s.doctrine.enforcement==='strict'?'restorative':'strict',r=O.policySR(s,'enforcement',value);const p=s.srOrganization.policies[0];assert.equal(p.version,r.version);assert.ok(!p.knownByPersonIds.includes('person:lu-zhiwei'));assert.equal(s.factsById[p.factId].retroactive,false);s.worldTick+=60;O.tickOrganization(s);assert.ok(p.knownByPersonIds.includes('person:lu-zhiwei'));});
check('SR-XF-027 AC01 distinguish purpose, real loss of control and fake claim',()=>{const f={kind:'harmful-act',act:'massacre',purpose:'cultivation',controlState:'controlled',damage:20};assert.equal(O.evaluateTaboo(f).taboo,true);assert.equal(O.evaluateTaboo({...f,purpose:'revenge'}).taboo,false);assert.equal(O.evaluateTaboo({...f,controlState:'lost-control'}).classification,'loss-of-control');assert.equal(O.evaluateTaboo({...f,claimedLossOfControl:true}).taboo,true);assert.equal(O.evaluateTaboo({...f,controlState:'lost-control'}).damage,20);});
check('SR-XF-027 AC02 same fact different actual resources/policy response',()=>{const s=setup(),id='fact:test:crime';s.factsById[id]={id,kind:'harmful-act',actorId:'person:lin-changfeng',act:'massacre',purpose:'cultivation',controlState:'controlled',damage:20};assert.equal(O.organizationResponse(s,id,{resources:60}).action,'investigate');s.srOrganization.knownCaseFactIds.push(id);assert.equal(O.organizationResponse(s,id,{resources:60}).action,'bounty');assert.equal(O.organizationResponse(s,id,{resources:0,enforcement:'strict'}).action,'sever-ties');});
check('SR-XF-027 AC03 escrow, genuine proof once, correction retains paid fact',()=>{const s=setup(),id='fact:test:crime';s.factsById[id]={id,kind:'harmful-act',actorId:'person:lin-changfeng',act:'massacre',purpose:'cultivation',controlState:'controlled',damage:20};s.srOrganization.knownCaseFactIds.push(id);const before=s.resources.jade,b=O.publishBounty(s,id);assert.equal(s.resources.jade,before-30);s.worldTick=60;O.acceptBounty(s,b.id);assert.throws(()=>O.redeemBounty(s,b.id,'invented-proof'));const proof='fact:test:captured';s.factsById[proof]={id:proof,kind:'bounty-capture',targetId:b.targetId,actorId:'person:master',outcome:'captured',atTick:60};O.redeemBounty(s,b.id,proof);assert.equal(s.resources.jade,before);assert.throws(()=>O.redeemBounty(s,b.id,proof));const correct='fact:test:correction';s.factsById[correct]={id:correct,kind:'case-correction',caseFactId:id,knownByPersonIds:['person:master']};O.correctBounty(s,b.id,correct);assert.equal(s.resources.jade,before);assert.ok(s.factsById[`fact:bounty-pay:${b.id}`]);assert.equal(s.srOrganization.corrections[0].damagePreserved,true);});
check('SR-XF-009 wages conserved separately from complete production output and batch replay',()=>{const s=setup(),p=s.personsById['person:lu-zhiwei'],b=s.buildings.find(b=>b.type==='farm')||{type:'farm',instanceId:'building:yunxiu:999',level:1};if(!s.buildingsById[b.instanceId])s.buildings.push({...b,id:999,x:3,y:3,condition:100,enabled:true,progress:0});E.initEconomy(s);s.workOrdersById[`work:production:${b.instanceId}`]={batch:1};const before=s.resources.jade+p.mind.purse,homeJade=s.resources.jade,st=s.stockpilesById[`stockpile:${b.instanceId}`],participants=[{person:p,share:1}],settle=(ps,t)=>{t.resources.herb+=20;t.resources.jade-=.8;ps[0].person.mind.purse+=.8;return true;};assert.equal(E.settleFiniteProduction(s,b,settle,participants),true);assert.equal(st.resources.herb,20);assert.ok(Math.abs(s.resources.jade-(homeJade-.8))<1e-9);assert.ok(Math.abs(s.resources.jade+p.mind.purse-before)<1e-9);const saved=cloneState(s);E.validateEconomy(saved);const snapshot=JSON.stringify(saved);assert.equal(E.settleFiniteProduction(saved,saved.buildingsById[b.instanceId],settle,[{person:saved.personsById[p.personId],share:1}]),false);assert.equal(JSON.stringify(saved),snapshot);});
check('SR-XF-009/011 workshop buyer funds gross proceeds including wages, finite capital preflight',()=>{const s=setup(),id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',x:4,y:3,level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);E.initEconomy(s);s.worldTick=300;const p=s.personsById['person:lu-zhiwei'],st=s.stockpilesById[`stockpile:${b.instanceId}`],merchant=s.stockpilesById['stockpile:qingxi'];s.workOrdersById[`work:production:${b.instanceId}`]={batch:1};const before=s.resources.jade+p.mind.purse+merchant.resources.jade;const settle=(ps,t)=>{t.resources.jade+=20;t.resources.jade-=.8;ps[0].person.mind.purse+=.8;return true;};assert.equal(E.settleFiniteProduction(s,b,settle,[{person:p,share:1}]),true);assert.ok(Math.abs(st.resources.jade-20)<1e-9);assert.ok(Math.abs(s.resources.jade+p.mind.purse+merchant.resources.jade+st.resources.jade-before)<1e-9);s.workOrdersById[`work:production:${b.instanceId}`].batch++;merchant.resources.jade=19;const snapshot=JSON.stringify(s);assert.equal(E.settleFiniteProduction(s,b,settle,[{person:p,share:1}]),false);assert.equal(JSON.stringify(s),snapshot);});
check('SR-XF-008 invitation rechecks restored workstation ingredients rather than permanent rejection cache',()=>{const s=setup(),p=s.personsById['person:lu-zhiwei'],id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',x:4,y:3,level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);E.initEconomy(s);s.worldTick=300;s.homeMemberIds.push(p.personId);p.wound=0;p.energy=100;p.mind.satiety=100;const first=P.inviteWork(s,p.personId,b.id);assert.equal(first.available,false);Object.assign(s.stockpilesById[`stockpile:${b.instanceId}`].resources,{wood:3,stone:2});const second=P.inviteWork(s,p.personId,b.id);assert.equal(second.available,true);assert.equal(second.accepted,true);assert.notEqual(second.signature,first.signature);});
check('SR-XF-009 actual patch restoration spends onsite body time and cancel refunds remaining once',()=>{let s=SIM.initial({sr:true});s.master.wound=0;s.master.energy=100;s.master.activityId=null;s.srEconomy.patches.herb.remaining=0;const before=s.resources.herb,result=SIM.dispatchCommand(s,{name:'replenishPatch',args:['herb']});assert.equal(result.status,'committed',result.message);s=result.state;assert.equal(s.srEconomy.patches.herb.remaining,0);assert.equal(s.resources.herb,before-4);const restored=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.equal(restored.activitiesById[restored.master.activityId].kind,'sr-replenish');for(let n=0;n<400;n++)SIM.tick(s,.1);assert.equal(s.srEconomy.patches.herb.remaining,160);assert.equal(s.master.activityId===null||s.activitiesById[s.master.activityId]?.kind==='facility',true);s.srEconomy.patches.herb.remaining=0;releaseBodyActivity(s,s.master);E.replenishPatch(s,'herb');const a=s.activitiesById[s.master.activityId];a.progressTicks=75;const jade=s.resources.jade,herb=s.resources.herb;E.cancelReplenish(s);assert.equal(s.resources.jade,jade+4);assert.equal(s.resources.herb,herb+2);assert.throws(()=>E.cancelReplenish(s));SIM.validateSave(JSON.parse(JSON.stringify(s)));});
check('SR-XF-010 remote body and migration locked destination cannot start or progress transport',()=>{const s=SIM.initial({sr:true}),source=s.stockpilesById['stockpile:yunxiu'],id='stockpile:transport-target';s.stockpilesById[id]={...structuredClone(source),id,resources:Object.fromEntries(Object.keys(source.resources).map(k=>[k,0]))};s.master.wound=0;s.master.energy=100;s.master.activityId=null;s.master.position={kind:'scene',sceneId:'scene:market',x:37,y:25};assert.throws(()=>E.startTransport(s,source.id,id,'person:master',{wood:1}),/真实在院/);s.master.position={kind:'scene',sceneId:'scene:yunxiu-courtyard',x:s.master.scenic.x,y:s.master.scenic.y};s.master.scenic={...s.master.scenic,...source.position,path:[]};const w=E.startTransport(s,source.id,id,'person:master',{wood:1});s.worldTick++;E.tickEconomy(s);assert.equal(s.workOrdersById[w.id].phase,'carrying');s.master.scenic.spatialEvacuationOrderId='work:test';const snapshot=s.stockpilesById[id].resources.wood;s.worldTick++;E.tickEconomy(s);assert.equal(s.stockpilesById[id].resources.wood,snapshot);delete s.master.scenic.spatialEvacuationOrderId;E.cancelTransport(s,w.id);});
check('SR-XF-011 merchant blocked route retains actual journey progress; reopening cannot teleport arrival',()=>{const s=SIM.initial({sr:true}),r=Object.values(s.srWorld.routes).find(r=>r.id.includes('bridge'));assert.ok(r);r.condition='blocked';for(let t=1;t<=600;t++){s.worldTick=t;E.tickEconomy(s);}const merchant=s.personsById['person:merchant-qingxi'];assert.equal(merchant.position.kind,'worldTravel');const trip=s.travelsById[s.srEconomy.merchantJourneyId];assert.equal(trip.progressTicks,0);r.condition='open';for(let t=601;t<900;t++){s.worldTick=t;E.tickEconomy(s);}assert.equal(trip.progressTicks,299);assert.equal(merchant.position.kind,'worldTravel');s.worldTick=900;E.tickEconomy(s);assert.equal(merchant.position.sceneId,'scene:yunxiu-courtyard');assert.equal(trip.status,'completed');assert.equal(s.srEconomy.merchantVisitEndsTick,1800);s.society.clock=s.time;SIM.validateSave(JSON.parse(JSON.stringify(s)));});
