check('SR-XF-026 office resignation and repeat acceptance preserve finite paycheck contract',()=>{const s=setup(),p=s.personsById['person:lu-zhiwei'];s.homeMemberIds=[p.personId];s.society.formal=true;p.realm=4;p.wound=0;p.mind.traits=[80,40,80,80,40];p.mind.relationships.master.trust=80;p.mind.relationships.master.respect=80;assert.equal(O.inviteOfficeSR(s,p.personId,'steward').accepted,true);O.resignOffice(s,p.personId,'steward');assert.equal(O.inviteOfficeSR(s,p.personId,'steward').accepted,true);assert.equal(s.srOrganization.offices.steward.status,'accepted');assert.equal(p.mind.office,'steward');const before=s.resources.jade+p.mind.purse;s.worldTick=s.ticksPerDay;O.tickOrganization(s);assert.equal(s.resources.jade+p.mind.purse,before);const purse=p.mind.purse;O.tickOrganization(s);assert.equal(p.mind.purse,purse);assert.equal(O.inviteOfficeSR(s,p.personId,'warden').accepted,false);});
check('SR-XF-027 repeated bounty acceptance preserves original actual proof window',()=>{const s=setup(),id='fact:review:crime';s.factsById[id]={id,kind:'harmful-act',actorId:'person:lin-changfeng',act:'massacre',purpose:'cultivation',damage:20};s.srOrganization.knownCaseFactIds.push(id);const bounty=O.publishBounty(s,id);s.worldTick=60;O.acceptBounty(s,bounty.id);s.worldTick=70;O.acceptBounty(s,bounty.id);assert.equal(s.srOrganization.bounties[bounty.id].acceptedTick,60);});
const craftSetup=()=>{const s=SIM.initial({sr:true});s.master.wound=0;s.master.energy=100;releaseBodyActivity(s,s.master);const id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'alchemy',buildingGridVersion:SIM.BUILDING_GRID.version,prefabId:'prefab:alchemy:units:v1',sceneId:'scene:yunxiu-courtyard',x:4,y:3,transform:{x:38,y:16,orientation:'south'},level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);E.initEconomy(s);return {s,b,site:s.stockpilesById[`stockpile:${b.instanceId}`]};};
check('SR-XF-009 actual craft requires transported ingredients and exclusive onsite station; wounded pause saves then resumes once',()=>{let {s,b,site}=craftSetup();assert.ok(E.craftAvailabilitySR(s,'heal').reasons.some(r=>r.includes('搬入')));const home=s.stockpilesById['stockpile:yunxiu'],totalHerb=home.resources.herb+site.resources.herb,before=s.pills.heal;let r=SIM.dispatchCommand(s,{name:'startTransport',args:[home.id,site.id,'person:master',{herb:10}]});assert.equal(r.status,'committed',r.message);s=r.state;for(let t=0;t<400;t++)SIM.tick(s,.1);assert.equal(s.stockpilesById[site.id].resources.herb,10);assert.equal(s.stockpilesById[home.id].resources.herb+s.stockpilesById[site.id].resources.herb,totalHerb);r=SIM.dispatchCommand(s,{name:'craftSR',args:['heal']});assert.equal(r.status,'committed',r.message);s=r.state;assert.equal(s.stockpilesById[site.id].resources.herb,0);const a=s.activitiesById[s.master.activityId],w=s.workOrdersById[a.workOrderId];assert.equal(w.progressTicks,0);for(let t=0;t<400&&w.progressTicks<20;t++)SIM.tick(s,.1);assert.equal(s.pills.heal,before);assert.ok(w.progressTicks>0);s.master.wound=50;const progress=w.progressTicks;for(let t=0;t<30;t++)SIM.tick(s,.1);assert.equal(w.progressTicks,progress);s=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.equal(s.workOrdersById[w.id].progressTicks,progress);s.master.wound=0;for(let t=0;t<230;t++)SIM.tick(s,.1);assert.equal(s.pills.heal,before+2);assert.equal(s.stockpilesById[site.id].pills.heal,2);assert.equal(s.stockpilesById[home.id].pills.heal,before);assert.equal(s.workOrdersById[w.id].phase,'completed');assert.ok(s.factsById[s.workOrdersById[w.id].resultFactId]);const again=SIM.validateSave(JSON.parse(JSON.stringify(s)));for(let t=0;t<30;t++)SIM.tick(again,.1);assert.equal(again.pills.heal,before+2);});
check('SR-XF-009 canceled partial pill craft returns only unworked inputs once and no pills',()=>{const {s,site}=craftSetup();site.resources.herb=10;const before=s.pills.heal;E.craftSR(s,'heal');const w=s.workOrdersById[s.activitiesById[s.master.activityId].workOrderId];w.progressTicks=100;const jade=s.resources.jade;const out=E.cancelCraftSR(s);assert.equal(out.refund.herb,5);assert.equal(site.resources.herb,5);assert.equal(s.resources.jade,jade+5);assert.equal(s.pills.heal,before);assert.throws(()=>E.cancelCraftSR(s));SIM.validateSave(JSON.parse(JSON.stringify(s)));});
check('SR-XF-009 paid legacy crafting retains remaining work without repay or offline output',()=>{const {s,site}=craftSetup();s.crafting={recipeId:'heal',remaining:10,total:20,yield:2};const jade=s.resources.jade,herb=site.resources.herb,pills=s.pills.heal;E.initEconomy(s);assert.equal(s.crafting,null);const w=s.workOrdersById[s.activitiesById[s.master.activityId].workOrderId];assert.equal(w.progressTicks,100);assert.equal(w.durationTicks,200);assert.equal(s.resources.jade,jade);assert.equal(site.resources.herb,herb);assert.equal(s.pills.heal,pills);const saved=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.equal(saved.workOrdersById[w.id].legacyPaid,true);});
check('SR-XF-010 gift recipients reveal identity and actual location without private inventory, handover once',()=>{const s=SIM.initial({sr:true}),p=s.personsById['person:lu-zhiwei'],home=s.stockpilesById['stockpile:yunxiu'],privateId='stockpile:lu-zhiwei';s.master.position={kind:'scene',sceneId:'scene:yunxiu-courtyard',x:s.master.scenic.x,y:s.master.scenic.y};s.master.scenic={...s.master.scenic,...home.position};p.position={kind:'scene',sceneId:'scene:yunxiu-courtyard',x:home.position.x+.7,y:home.position.y};p.mind.scenic={...p.mind.scenic,x:home.position.x+.7,y:home.position.y};const v=E.viewEconomy(s),recipient=v.giftRecipients.find(r=>r.stockpileId===privateId);assert.ok(recipient);assert.equal(recipient.name,p.name);assert.equal(Object.hasOwn(recipient,'resources'),false);const q=s.stockpilesById[privateId].resources.herb,before=home.resources.herb;E.transferProperty(s,home.id,privateId,'herb',3);assert.equal(home.resources.herb,before-3);assert.equal(s.stockpilesById[privateId].resources.herb,q+3);assert.throws(()=>E.transferProperty(s,privateId,home.id,'herb',1),/无权/);});
check('SR-XF-011 external wholesale pays only actual acquired cargo from persistent bounded customer money',()=>{const s=SIM.initial({sr:true});s.master.activityId=null;s.master.position={kind:'scene',sceneId:'scene:market',x:37,y:25};const merchant=s.personsById['person:merchant-qingxi'];merchant.position={kind:'scene',sceneId:'scene:market',x:37,y:25};s.stockpilesById['stockpile:qingxi'].position={sceneId:'scene:market',x:37,y:25};s.srEconomy.merchantSchedulePhase='market';s.srEconomy.merchantArrivalTick=99999;s.srEconomy.merchantVisitEndsTick=100999;s.srEconomy.marketRestockTick=99999;s.stockpilesById['stockpile:sr-party']??={id:'stockpile:sr-party',ownerId:'person:master',custodianId:'person:master',access:'private',capacity:400,position:{sceneId:'scene:market',x:37,y:25},resources:Object.fromEntries(Object.keys(s.resources).map(k=>[k,0]))};const m=s.stockpilesById['stockpile:qingxi'],c=s.stockpilesById['stockpile:wholesale-treasury'],party=s.stockpilesById['stockpile:sr-party'];party.resources.wood=10;const q=party.resources.wood+m.resources.wood+c.resources.wood,money=party.resources.jade+m.resources.jade+c.resources.jade;E.marketTrade(s,'wood','sell',1);assert.equal(s.srEconomy.resaleInventory.wood,10);const before=c.resources.jade;s.worldTick=2400;E.tickEconomy(s);assert.equal(c.resources.jade,before-18);assert.equal(s.srEconomy.wholesale.windowSpent,18);assert.equal(s.srEconomy.resaleInventory.wood,0);assert.equal(party.resources.wood+m.resources.wood+c.resources.wood,q);assert.equal(party.resources.jade+m.resources.jade+c.resources.jade,money);const snapshot=JSON.stringify(s);E.tickEconomy(s);assert.equal(JSON.stringify(s),snapshot);s.worldTick=4800;E.tickEconomy(s);assert.equal(c.resources.jade,before-18);assert.ok(s.factsById['fact:wholesale:2400']);E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-009 covered harvest anchor selects reachable bounded feet rather than infinite moving',()=>{const s=SIM.initial({sr:true});s.master.wound=0;s.master.energy=100;releaseBodyActivity(s,s.master);const id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'house',buildingGridVersion:SIM.BUILDING_GRID.version,prefabId:'prefab:house:units:v1',sceneId:'scene:yunxiu-courtyard',x:5,y:4,transform:{x:38,y:22,orientation:'south'},level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);s.spatial.geometryRevision++;s.srEconomy.patches.wood.position={sceneId:'scene:yunxiu-courtyard',x:39,y:23};const r=E.startMasterHarvest(s,'wood'),a=s.activitiesById[r.id];assert.notDeepEqual(a.target,{x:39,y:23});assert.ok(Math.hypot(a.target.x-39,a.target.y-23)<=3);for(let t=0;t<600&&s.master.activityId===a.id;t++)SIM.tick(s,.1);assert.notEqual(s.master.activityId,a.id);assert.equal(s.stockpilesById['stockpile:carried:master'].resources.wood,12);});
check('SR-XF-027 hidden case/correction cannot leak through legal proof projection',()=>{const s=setup(),crime='fact:private:crime',evidence='fact:private:evidence';s.factsById[crime]={id:crime,kind:'harmful-act',actorId:'person:lin-changfeng',act:'massacre',purpose:'cultivation',damage:20};s.factsById[evidence]={id:evidence,kind:'observation',caseFactId:crime,text:'private murder detail',knownByPersonIds:['person:lin-changfeng']};assert.equal(O.viewOrganization(s).caseCandidates.length,0);s.factsById[evidence].knownByPersonIds.push('person:master');assert.equal(O.viewOrganization(s).caseCandidates[0].evidence[0].id,evidence);O.knowCase(s,crime,[evidence]);assert.ok(O.viewOrganization(s).cases.some(c=>c.factId===crime));});
check('SR-XF-009/011 merchant physically collects one toolkit before departing and finite customer pays after actual return',()=>{const s=SIM.initial({sr:true}),id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',buildingGridVersion:SIM.BUILDING_GRID.version,prefabId:'prefab:workshop:units:v1',sceneId:'scene:yunxiu-courtyard',x:4,y:3,transform:{x:38,y:16,orientation:'south'},level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);s.spatial.geometryRevision++;E.initEconomy(s);for(let t=1;t<=300;t++){s.worldTick=t;E.tickEconomy(s);}const merchant=s.personsById['person:merchant-qingxi'],m=s.stockpilesById['stockpile:qingxi'],st=s.stockpilesById[`stockpile:${b.instanceId}`],customer=s.stockpilesById['stockpile:wholesale-treasury'],worker=s.personsById['person:lu-zhiwei'],wid=`work:production:${b.instanceId}`;merchant.wound=0;merchant.energy=100;s.workOrdersById[wid]={id:wid,batch:1};const money=m.resources.jade+s.resources.jade+st.resources.jade+worker.mind.purse,settle=(ps,t)=>{t.resources.jade+=20;t.resources.jade-=.8;ps[0].person.mind.purse+=.8;return true;},parts=[{person:worker,share:1}],feet={...merchant.position};assert.equal(E.settleFiniteProduction(s,b,settle,parts),false);const w=s.workOrdersById[`work:merchant-collection:${b.instanceId}:1`];assert.equal(w.phase,'to-source');assert.equal(st.resources.jade,0);assert.equal(s.srEconomy.commonGoods.length,0);s.srEconomy.merchantVisitEndsTick=301;for(let n=0;n<500&&w.phase!=='waiting-for-goods';n++){s.worldTick++;E.tickEconomy(s);}assert.equal(w.phase,'waiting-for-goods');assert.notDeepEqual(merchant.position,feet);assert.equal(merchant.position.kind,'scene');assert.equal(s.srEconomy.merchantSchedulePhase,'home');E.validateEconomy(JSON.parse(JSON.stringify(s)));assert.equal(E.settleFiniteProduction(s,b,settle,parts),true);assert.ok(Math.abs(st.resources.jade-20)<1e-9);assert.equal(s.srEconomy.commonGoods.length,1);assert.equal(s.srEconomy.commonGoods[0].ownerId,merchant.personId);assert.ok(Math.abs(m.resources.jade+s.resources.jade+st.resources.jade+worker.mind.purse-money)<1e-9);assert.equal(w.phase,'carrying');assert.equal(E.settleFiniteProduction(s,b,settle,parts),false);for(let n=0;n<500&&w.phase!=='delivered';n++){s.worldTick++;E.tickEconomy(s);}assert.equal(w.phase,'delivered');assert.equal(merchant.activityId,null);const before=customer.resources.jade;s.worldTick++;E.tickEconomy(s);assert.equal(merchant.position.kind,'worldTravel');assert.equal(customer.resources.jade,before);for(let n=0;n<300;n++){s.worldTick++;E.tickEconomy(s);}assert.equal(merchant.position.sceneId,'scene:market');while(s.worldTick<2400){s.worldTick++;E.tickEconomy(s);}assert.equal(customer.resources.jade,before-22);assert.equal(s.srEconomy.commonGoods[0].ownerId,'person:wholesale-buyer');assert.equal(s.srEconomy.commonGoods.length,1);E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-009 workshop payroll shortfall is deducted from actual batch proceeds, never negative public money',()=>{const s=setup(),id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',x:4,y:3,level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);E.initEconomy(s);s.worldTick=300;s.resources.jade=0;const p=s.personsById['person:lu-zhiwei'],m=s.stockpilesById['stockpile:qingxi'],st=s.stockpilesById[`stockpile:${b.instanceId}`],money=m.resources.jade+p.mind.purse;s.workOrdersById[`work:production:${b.instanceId}`]={batch:1};assert.equal(E.settleFiniteProduction(s,b,(ps,t)=>{t.resources.jade+=20;t.resources.jade-=.8;ps[0].person.mind.purse+=.8;return true;},[{person:p,share:1}]),true);assert.equal(s.resources.jade,0);assert.ok(Math.abs(st.resources.jade-19.2)<1e-9);assert.ok(Math.abs(m.resources.jade+p.mind.purse+st.resources.jade-money)<1e-9);assert.ok(Math.abs(s.factsById[`fact:production:${b.instanceId}:1`].wagesFromProceeds-.8)<1e-9);E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-011 prior SR save missing wholesale fields migrates once without duplicate capital or identities',()=>{const original=SIM.initial({sr:true});delete original.srEconomy.wholesale;delete original.srEconomy.resaleInventory;delete original.srEconomy.commonGoods;delete original.personsById['person:wholesale-buyer'];delete original.stockpilesById['stockpile:wholesale-treasury'];const s=SIM.validateSave(JSON.parse(JSON.stringify(original)));assert.equal(s.stockpilesById['stockpile:wholesale-treasury'].resources.jade,E.WHOLESALE_DEFINITION.lifetimeTreasury);const count=Object.keys(s.personsById).length,next=s.society.nextPersonId;s.stockpilesById['stockpile:wholesale-treasury'].resources.jade-=12;s.srEconomy.wholesale.spentLifetime=12;E.initEconomy(s);E.initEconomy(s);assert.equal(Object.keys(s.personsById).length,count);assert.equal(s.society.nextPersonId,next);assert.equal(s.stockpilesById['stockpile:wholesale-treasury'].resources.jade,E.WHOLESALE_DEFINITION.lifetimeTreasury-12);const raw=JSON.stringify(s);assert.equal(JSON.stringify(SIM.validateSave(JSON.parse(raw))),raw);});
check('SR-XF-009/011 canceling unpaid production releases merchant collection and preserves costs once',()=>{const s=SIM.initial({sr:true}),id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',buildingGridVersion:SIM.BUILDING_GRID.version,prefabId:'prefab:workshop:units:v1',sceneId:'scene:yunxiu-courtyard',x:4,y:3,transform:{x:38,y:16,orientation:'south'},level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);s.spatial.geometryRevision++;E.initEconomy(s);for(let t=1;t<=300;t++){s.worldTick=t;E.tickEconomy(s);}const merchant=s.personsById['person:merchant-qingxi'],m=s.stockpilesById['stockpile:qingxi'],st=s.stockpilesById[`stockpile:${b.instanceId}`],wid=`work:production:${b.instanceId}`,rid=`reservation:input:${b.instanceId}`;merchant.wound=0;merchant.energy=100;s.workOrdersById[wid]={id:wid,kind:'production',targetId:b.instanceId,batch:1,phase:'active',progressTicks:0,durationTicks:100,reservationId:rid};s.reservationsById[rid]={id:rid,kind:'materials',workOrderId:wid,cost:{wood:3,stone:2}};const cash=m.resources.jade;assert.equal(E.settleFiniteProduction(s,b,(_ps,t)=>{t.resources.jade+=20;return true;},[]),false);const collection=s.workOrdersById[`work:merchant-collection:${b.instanceId}:1`];assert.equal(collection.phase,'to-source');cancelProduction(s,b.id);assert.equal(collection.phase,'cancelled');assert.equal(merchant.activityId,null);assert.equal(st.resources.wood,3);assert.equal(st.resources.stone,2);assert.equal(m.resources.jade,cash);assert.equal(s.srEconomy.commonGoods.length,0);assert.throws(()=>cancelProduction(s,b.id));E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-009/010 old SR pills migrate once into public stock and total becomes read-only through clone/reload',()=>{const s=SIM.initial({sr:true});delete s.srEconomy.pillInventoryVersion;delete s.srEconomy.pillAllocations;delete s.factsById['fact:pill-stock-migration:v1'];for(const st of Object.values(s.stockpilesById))delete st.pills;Object.defineProperty(s,'pills',{configurable:true,enumerable:true,writable:true,value:{qi:2,spirit:1,heal:3,foundation:1}});E.initPillInventory(s);assert.equal(s.stockpilesById['stockpile:yunxiu'].pills.heal,3);assert.equal(s.pills.foundation,1);E.initPillInventory(s);assert.equal(s.stockpilesById['stockpile:yunxiu'].pills.heal,3);assert.throws(()=>{s.pills.heal++;},/只读/);const cloned=cloneState(s);assert.throws(()=>{cloned.pills.heal--;},/只读/);const saved=SIM.validateSave(JSON.parse(JSON.stringify(s)));assert.equal(saved.pills.heal,3);assert.equal(saved.stockpilesById['stockpile:yunxiu'].pills.heal,3);assert.equal(saved.factsById['fact:pill-stock-migration:v1'].quantities.heal,3);});
check('SR-XF-009/010 distant medicine requires actual public-command pickup before consuming once',()=>{let s=SIM.initial({sr:true});releaseBodyActivity(s,s.master);s.master.wound=35;s.master.energy=100;s.stockpilesById['stockpile:yunxiu'].pills.heal=0;E.grantPills(s,'stockpile:yunxiu','heal',1,{factId:'fact:qa:one-heal'});s.master.scenic={...s.master.scenic,x:40,y:35,path:[],goal:null};assert.equal(E.availablePills(s,'person:master','heal'),0);assert.throws(()=>BASE.masterPill(s,'heal'),/不足/);const r=SIM.dispatchCommand(s,{name:'preparePillUse',args:['heal']});assert.equal(r.result.pending,true);s=r.state;assert.equal(s.pills.heal,1);assert.equal(s.stockpilesById['stockpile:yunxiu'].pills.heal,0);for(let t=0;t<800&&s.workOrdersById[r.result.id].phase!=='delivered';t++)SIM.tick(s,.1);assert.equal(s.workOrdersById[r.result.id].phase,'delivered');assert.equal(s.stockpilesById['stockpile:carried:master'].pills.heal,1);assert.equal(s.pills.heal,1);s=SIM.validateSave(JSON.parse(JSON.stringify(s)));const used=SIM.dispatchCommand(s,{name:'masterPill',args:['heal']});s=used.state;assert.equal(s.pills.heal,0);assert.equal(s.master.wound,10);assert.equal(s.stats.consumed,1);assert.throws(()=>SIM.dispatchCommand(s,{name:'masterPill',args:['heal']}));assert.equal(Object.values(s.srEconomy.pillAllocations).filter(a=>a.recipeId==='heal'&&a.phase==='consumed').length,1);});
check('SR-XF-010 medicine gift becomes recipient private stock and cannot be secretly consumed by master',()=>{const s=SIM.initial({sr:true}),home=s.stockpilesById['stockpile:yunxiu'],p=s.personsById['person:lu-zhiwei'],privateId='stockpile:lu-zhiwei',feet=buildingAccess(s,s.buildings.find(b=>b.type==='hall'));s.master.scenic={...s.master.scenic,...feet,path:[],goal:null};p.position={kind:'scene',sceneId:'scene:yunxiu-courtyard',x:feet.x+.5,y:feet.y};Object.assign(p.mind.scenic,{x:feet.x+.5,y:feet.y,path:[],goal:null});home.pills.heal=1;s.stockpilesById[privateId].pills.heal=0;E.transferProperty(s,home.id,privateId,'pill:heal',1);assert.equal(home.pills.heal,0);assert.equal(s.stockpilesById[privateId].pills.heal,1);assert.equal(s.pills.heal,0);assert.equal(E.availablePills(s,'person:master','heal'),0);assert.equal(E.availablePills(s,p.personId,'heal'),1);assert.throws(()=>E.transferProperty(s,privateId,home.id,'pill:heal',1),/无权/);p.wound=35;BASE.consumePill(s,'heal',p,{silent:true});assert.equal(p.wound,10);assert.equal(s.stockpilesById[privateId].pills.heal,0);E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-010 reserved medicine moves with holder and cancel outside source leaves one true-location dose',()=>{const s=SIM.initial({sr:true}),home=s.stockpilesById['stockpile:yunxiu'],feet=buildingAccess(s,s.buildings.find(b=>b.type==='hall'));s.master.scenic={...s.master.scenic,...feet,path:[],goal:null};home.pills.foundation=1;const a=E.reserveAccessiblePills(s,'person:master','foundation',1,{reservationId:'pill-allocation:qa:foundation'});assert.equal(home.pills.foundation,0);assert.equal(s.pills.foundation,1);assert.equal(E.availablePills(s,'person:master','foundation'),0);s.master.scenic.x=40;s.master.scenic.y=35;E.refundPillAllocation(s,a);assert.equal(home.pills.foundation,0);assert.equal(a.returnedTo.length,1);const dropped=s.stockpilesById[a.returnedTo[0].stockpileId];assert.equal(dropped.pills.foundation,1);assert.equal(dropped.position.x,40);assert.equal(dropped.position.y,35);assert.equal(s.pills.foundation,1);assert.throws(()=>E.refundPillAllocation(s,a));assert.throws(()=>E.consumePillAllocation(s,a));E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-010 physically carried medicine may be used after actual arrival away but not during travel',()=>{const s=SIM.initial({sr:true}),id=E.carriedStockpile(s),carried=s.stockpilesById[id];carried.pills.heal=1;s.master.position={kind:'scene',sceneId:'scene:market',x:37,y:25};s.master.location={kind:'local',sceneId:'scene:market',x:37,y:25};s.master.wound=35;assert.equal(E.availablePills(s,'person:master','heal'),1);BASE.masterPill(s,'heal');assert.equal(carried.pills.heal,0);assert.equal(s.master.wound,10);carried.pills.heal=1;s.master.location={kind:'travel',travelId:'travel:qa'};s.master.position={kind:'worldTravel',travelId:'travel:qa'};assert.equal(E.availablePills(s,'person:master','heal'),0);assert.throws(()=>BASE.masterPill(s,'heal'));assert.equal(carried.pills.heal,1);});
check('SR-XF-008/010 NPC independently consumes its only private dose with public medicine empty',()=>{const s=SIM.initial({sr:true}),p=s.personsById['person:lu-zhiwei'],privateId='stockpile:lu-zhiwei';if(!s.homeMemberIds.includes(p.personId))s.homeMemberIds.push(p.personId);for(const st of Object.values(s.stockpilesById))if(st.pills)st.pills.heal=0;s.stockpilesById[privateId].pills.heal=1;releaseBodyActivity(s,p);p.wound=35;p.energy=100;p.mind.satiety=100;p.mind.lastPillDay=-1;p.mind.restrictedUntil=0;s.doctrine.pillRule='permission';const before=s.stats.consumed;assert.equal(s.pills.heal,0);assert.equal(E.availablePills(s,p.personId,'heal'),1);for(let n=0;n<300&&s.stockpilesById[privateId].pills.heal>0;n++)SIM.tick(s,.1);assert.equal(s.stockpilesById[privateId].pills.heal,0);assert.equal(s.stockpilesById['stockpile:yunxiu'].pills.heal,0);assert.equal(s.stats.consumed,before+1);assert.ok(p.mind.lastPillDay>=0);assert.equal(s.society.secrets.some(e=>e.discipleId===p.id&&e.kind==='pill'),false);assert.ok(p.wound<=10);SIM.validateSave(JSON.parse(JSON.stringify(s)));});
check('SR-XF-010 legacy paid unrefined breakthrough dose migrates held once and refunds without another charge',()=>{const s=SIM.initial({sr:true}),home=s.stockpilesById['stockpile:yunxiu'],feet=buildingAccess(s,s.buildings.find(b=>b.type==='hall')),id='order:cultivation:qa-legacy-dose';home.pills.foundation=0;s.master.scenic={...s.master.scenic,...feet,path:[],goal:null};s.srCultivation.orders[id]={id,kind:'breakthrough',personId:'person:master',parameters:{pillCost:1},reservedPill:1,consumed:false,createdTick:s.worldTick,sourceStockpileId:home.id,phase:'reserved'};E.initPillInventory(s);const o=s.srCultivation.orders[id],a=o.pillAllocation;assert.equal(o.reservedPill,undefined);assert.equal(a.phase,'reserved');assert.equal(home.pills.foundation,0);assert.equal(s.pills.foundation,1);E.initPillInventory(s);assert.equal(s.pills.foundation,1);E.refundPillAllocation(s,a);assert.equal(home.pills.foundation,1);assert.equal(s.pills.foundation,1);assert.throws(()=>E.refundPillAllocation(s,a));E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-010 legacy already-refined breakthrough dose remains consumed across migration',()=>{const s=SIM.initial({sr:true}),home=s.stockpilesById['stockpile:yunxiu'],id='order:cultivation:qa-legacy-refined';home.pills.foundation=0;s.srCultivation.orders[id]={id,kind:'breakthrough',personId:'person:master',parameters:{pillCost:1},reservedPill:1,consumed:true,refineStarted:true,createdTick:s.worldTick,sourceStockpileId:home.id,phase:'executing'};E.initPillInventory(s);const a=s.srCultivation.orders[id].pillAllocation;assert.equal(a.phase,'consumed');assert.equal(s.pills.foundation,0);assert.equal(home.pills.foundation,0);assert.throws(()=>E.refundPillAllocation(s,a));assert.throws(()=>E.consumePillAllocation(s,a));E.initPillInventory(s);assert.equal(s.pills.foundation,0);E.validateEconomy(JSON.parse(JSON.stringify(s)));});
check('SR-XF-008/010 NPC autonomously walks to a distant public medicine cabinet before taking and consuming',()=>{const s=SIM.initial({sr:true}),p=s.personsById['person:lu-zhiwei'],home=s.stockpilesById['stockpile:yunxiu'];if(!s.homeMemberIds.includes(p.personId))s.homeMemberIds.push(p.personId);for(const st of Object.values(s.stockpilesById))if(st.pills)st.pills.heal=0;home.pills.heal=1;releaseBodyActivity(s,p);p.wound=35;p.energy=100;p.mind.satiety=100;p.mind.lastPillDay=-1;p.mind.restrictedUntil=0;p.mind.scenic={...p.mind.scenic,x:40,y:35,path:[],goal:null};s.doctrine.pillRule='shared';const before=s.stats.consumed;assert.equal(E.availablePills(s,p.personId,'heal'),0);for(let n=0;n<200&&!Object.values(s.workOrdersById).some(w=>w.kind==='transport'&&w.carrierId===p.personId&&w.cargo['pill:heal']);n++)SIM.tick(s,.1);const w=Object.values(s.workOrdersById).find(w=>w.kind==='transport'&&w.carrierId===p.personId&&w.cargo['pill:heal']);assert.ok(w);assert.equal(s.stats.consumed,before);assert.equal(w.phase,'to-source');assert.equal(s.pills.heal,1);for(let n=0;n<1000&&s.stats.consumed===before;n++)SIM.tick(s,.1);assert.equal(w.phase,'delivered');assert.equal(s.stats.consumed,before+1);assert.equal(home.pills.heal,0);assert.equal(s.stockpilesById[w.targetStockpileId].pills.heal,0);assert.ok(p.wound<=10);SIM.validateSave(JSON.parse(JSON.stringify(s)));});
check('SR-XF-008 expired accepted invitation is reconsidered while repeated current promise never extends',()=>{const s=setup(),p=s.personsById['person:lu-zhiwei'],id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'workshop',x:4,y:3,level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);E.initEconomy(s);s.worldTick=300;if(!s.homeMemberIds.includes(p.personId))s.homeMemberIds.push(p.personId);p.wound=0;p.energy=100;p.mind.satiety=100;p.mind.traits=[80,40,80,80,40];p.mind.relationships.master.trust=80;Object.assign(s.stockpilesById[`stockpile:${b.instanceId}`].resources,{wood:12,stone:8});const first=P.inviteWork(s,p.personId,b.id);assert.equal(first.accepted,true);const end=p.schedule.commitUntilTick;for(let n=1;n<240;n+=11){s.worldTick=first.atTick+n;assert.deepEqual(P.inviteWork(s,p.personId,b.id),first);assert.equal(p.schedule.commitUntilTick,end);}s.worldTick=end;const next=P.inviteWork(s,p.personId,b.id);assert.equal(next.accepted,true);assert.equal(next.signature,first.signature);assert.equal(next.atTick,end);assert.equal(p.schedule.commitUntilTick,end+P.AUTONOMY.commitTicks);p.wound=35;const hurt=P.inviteWork(s,p.personId,b.id);assert.equal(hurt.accepted,false);assert.match(hurt.publicReason,/伤势/);});
check('SR-XF-008 new invitation after actual job change renews only that voluntary promise; command replay preserves autonomous state',()=>{let s=SIM.initial({sr:true}),p=s.personsById['person:lu-zhiwei'],id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type:'farm',buildingGridVersion:SIM.BUILDING_GRID.version,prefabId:'prefab:farm:units:v1',sceneId:'scene:yunxiu-courtyard',x:4,y:3,transform:{x:38,y:16,orientation:'south'},level:1,condition:100,enabled:true,progress:0};s.buildings.push(b);s.spatial.geometryRevision++;E.initEconomy(s);if(!s.homeMemberIds.includes(p.personId))s.homeMemberIds.push(p.personId);p.wound=0;p.energy=100;p.xp=0;p.mind.satiety=100;p.mind.traits=[80,40,80,80,40];p.mind.relationships.master.trust=80;const command={name:'inviteWork',args:[p.personId,b.instanceId],id:'command:qa:finite-promise'};const first=SIM.dispatchCommand(s,command);s=first.state;p=s.personsById[p.personId];assert.equal(first.result.accepted,true);for(let n=0;n<300;n++)SIM.tick(s,.1);assert.ok(s.worldTick>=first.result.atTick+P.AUTONOMY.commitTicks);assert.ok(p.job!==b.id||p.mind.activity!=='work','the elapsed natural rest phase must end the original work promise');const state=JSON.stringify(s),job=p.job,act=p.mind.activity,until=p.schedule.commitUntilTick;const replay=SIM.dispatchCommand(s,command);assert.equal(replay.replayed,true);assert.equal(JSON.stringify(replay.state),state);assert.equal(replay.state.personsById[p.personId].job,job);assert.equal(replay.state.personsById[p.personId].mind.activity,act);assert.equal(replay.state.personsById[p.personId].schedule.commitUntilTick,until);s=replay.state;const current=s.personsById[p.personId];current.energy=100;current.mind.satiety=100;current.wound=0;const renewed=SIM.dispatchCommand(s,{name:'inviteWork',args:command.args,id:'command:qa:finite-promise-renew'});assert.equal(renewed.result.accepted,true);assert.equal(renewed.result.atTick,s.worldTick);assert.equal(renewed.state.personsById[p.personId].job,b.id);assert.equal(renewed.state.personsById[p.personId].mind.activity,'work');assert.equal(renewed.state.personsById[p.personId].schedule.commitUntilTick,s.worldTick+P.AUTONOMY.commitTicks);SIM.validateSave(JSON.parse(JSON.stringify(renewed.state)));});
